create extension if not exists pgcrypto;
create type public.user_role as enum ('admin', 'editor');
create type public.registration_status as enum ('New', 'Reviewed', 'Contacted', 'Approved', 'Rejected');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text not null, role public.user_role not null default 'editor', created_at timestamptz not null default now());
create table public.registrations (id uuid primary key default gen_random_uuid(), registration_number text unique not null, full_name text not null, country text not null, city text not null, occupation text not null, mobile_number text not null, email text not null, age int not null check (age between 13 and 120), comments text, privacy_consent boolean not null default false, status public.registration_status not null default 'New', admin_notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.website_content (id uuid primary key default gen_random_uuid(), section_key text unique not null, content jsonb not null default '{}', is_published boolean not null default true, updated_at timestamptz not null default now());
create table public.services (id uuid primary key default gen_random_uuid(), title text not null, description text not null, icon text not null default 'Sparkles', is_active boolean not null default true, sort_order int not null default 0, created_at timestamptz not null default now());
create table public.site_settings (id uuid primary key default gen_random_uuid(), setting_key text unique not null, setting_value text not null default '', updated_at timestamptz not null default now());
create table public.contact_enquiries (id uuid primary key default gen_random_uuid(), name text not null, email text not null, mobile text, message text not null, status text not null default 'New', created_at timestamptz not null default now());
create table public.email_logs (id uuid primary key default gen_random_uuid(), registration_id uuid references public.registrations(id) on delete set null, recipient text not null, email_type text not null, status text not null, error_message text, sent_at timestamptz, created_at timestamptz not null default now());
create table public.admin_audit_logs (id uuid primary key default gen_random_uuid(), admin_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id uuid, created_at timestamptz not null default now());
create index registrations_created_at_idx on public.registrations(created_at desc); create index registrations_email_idx on public.registrations(email); create index registrations_country_city_idx on public.registrations(country, city);
create or replace function public.create_registration(p_full_name text, p_country text, p_city text, p_occupation text, p_mobile_number text, p_email text, p_age int, p_comments text, p_privacy_consent boolean) returns text language plpgsql security definer set search_path = public as $$ declare new_id uuid; new_number text; begin insert into registrations(full_name,country,city,occupation,mobile_number,email,age,comments,privacy_consent) values (p_full_name,p_country,p_city,p_occupation,p_mobile_number,p_email,p_age,p_comments,p_privacy_consent) returning id into new_id; new_number := 'SK-' || extract(year from now())::text || '-' || lpad((select count(*)::text from registrations where extract(year from created_at)=extract(year from now()))::text, 6, '0'); update registrations set registration_number = new_number where id = new_id; return new_number; end; $$;
alter table profiles enable row level security; alter table registrations enable row level security; alter table website_content enable row level security; alter table services enable row level security; alter table site_settings enable row level security; alter table contact_enquiries enable row level security; alter table email_logs enable row level security; alter table admin_audit_logs enable row level security;
create policy "public cannot read registrations" on registrations for select using (false);
create policy "admins manage registrations" on registrations for all using (exists (select 1 from profiles where profiles.id=auth.uid() and profiles.role='admin'));
create policy "public read published content" on website_content for select using (is_published = true); create policy "public read active services" on services for select using (is_active = true);
